import React, { useState, useEffect, useCallback } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { blogPostsApi } from '../api/blogPostsApi';
import { withTokenExpiry } from '../api/authApi';
import { useAuth } from '../context/AuthContext';
import { useApp } from '../context/AppContext';
import { Card, SectionHeader, Badge, ErrorCard, Empty } from '../components/ui/UI';
import s from './BlogsPage.module.css';

const STATUS_VARIANT = { draft: 'default', published: 'success' };

function formatDate(iso) {
  if (!iso) return '';
  try { return new Date(iso).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }); }
  catch { return iso; }
}

export function BlogsPage() {
  const { toast } = useApp();
  const { goScreen, logout } = useAuth();
  const authCtx = { goScreen, logout };

  const [view, setView] = useState('list'); // 'list' | 'editor' | 'reader'
  const [posts, setPosts] = useState(null);
  const [filter, setFilter] = useState('all');
  const [loadError, setLoadError] = useState(null);
  const [activePost, setActivePost] = useState(null); // full post, for editor/reader
  const [deletingId, setDeletingId] = useState(null);

  const load = useCallback(() => {
    withTokenExpiry(blogPostsApi.list(), authCtx)
      .then(d => setPosts(d?.items || []))
      .catch(e => { if (e?.code !== 'TokenExpired') setLoadError(e.message || 'Could not load your posts.'); });
    // eslint-disable-next-line
  }, []);

  useEffect(() => { load(); }, [load]);

  const filteredPosts = (posts || []).filter(p => filter === 'all' || p.status === filter);

  const openNew = () => {
    setActivePost({ post_id: null, title: '', markdown_content: '', status: 'draft', author: '', cover_image_url: '' });
    setView('editor');
  };

  const openEdit = async (postId) => {
    try {
      const full = await withTokenExpiry(blogPostsApi.get(postId), authCtx);
      setActivePost(full);
      setView('editor');
    } catch (e) {
      if (e?.code !== 'TokenExpired') toast({ type: 'error', message: e.message || 'Could not load that post.' });
    }
  };

  const openReader = async (postId) => {
    try {
      const full = await withTokenExpiry(blogPostsApi.get(postId), authCtx);
      setActivePost(full);
      setView('reader');
    } catch (e) {
      if (e?.code !== 'TokenExpired') toast({ type: 'error', message: e.message || 'Could not load that post.' });
    }
  };

  const handleDelete = async (postId) => {
    if (!window.confirm('Delete this post? This cannot be undone.')) return;
    setDeletingId(postId);
    try {
      await withTokenExpiry(blogPostsApi.delete(postId), authCtx);
      setPosts(prev => (prev || []).filter(p => p.post_id !== postId));
      toast({ type: 'success', message: '✓ Post deleted.' });
    } catch (e) {
      if (e?.code !== 'TokenExpired') toast({ type: 'error', message: e.message || 'Could not delete that post.' });
    } finally {
      setDeletingId(null);
    }
  };

  const handleSaved = (saved) => {
    setActivePost(saved);
    setView('reader');
    load();
    toast({ type: 'success', message: '✓ Post saved.' });
  };

  if (view === 'editor') {
    return (
      <BlogEditor
        post={activePost}
        onCancel={() => setView(activePost?.post_id ? 'reader' : 'list')}
        onSaved={handleSaved}
        authCtx={authCtx}
      />
    );
  }

  if (view === 'reader' && activePost) {
    return (
      <BlogReader
        post={activePost}
        onBack={() => setView('list')}
        onEdit={() => setView('editor')}
      />
    );
  }

  return (
    <div className={s.page}>
      <SectionHeader
        title="Blogs"
        subtitle="Write and manage blog posts using Markdown — published posts are ready to share, drafts stay private to you."
        right={<button type="button" className={s.newBtn} onClick={openNew}>+ New Post</button>}
      />

      <div className={s.filterRow}>
        {[['all', 'All'], ['draft', 'Drafts'], ['published', 'Published']].map(([value, label]) => (
          <button
            key={value} type="button"
            className={`${s.filterBtn} ${filter === value ? s.filterActive : ''}`}
            onClick={() => setFilter(value)}
          >
            {label}
          </button>
        ))}
      </div>

      {loadError && <ErrorCard message={loadError} />}

      {posts === null && !loadError && <div className={s.loadingRow}><span className={s.spinner} />Loading posts…</div>}

      {posts !== null && filteredPosts.length === 0 && (
        <Empty icon="📝" title="No posts yet" body="Click “New Post” to write your first blog post in Markdown." />
      )}

      <div className={s.grid}>
        {filteredPosts.map(post => (
          <Card key={post.post_id} padded={false} className={s.postCard}>
            {post.cover_image_url && <img className={s.coverThumb} src={post.cover_image_url} alt="" />}
            <div className={s.postCardBody}>
              <div className={s.postCardHead}>
                <Badge variant={STATUS_VARIANT[post.status] || 'default'}>{post.status}</Badge>
                <span className={s.postDate}>{formatDate(post.updated_at)}</span>
              </div>
              <div className={s.postTitle} onClick={() => openReader(post.post_id)}>{post.title}</div>
              {post.excerpt && <div className={s.postExcerpt}>{post.excerpt}</div>}
              {post.author && <div className={s.postAuthor}>By {post.author}</div>}
              <div className={s.postCardActions}>
                <button type="button" className={s.cardActionBtn} onClick={() => openReader(post.post_id)}>Read</button>
                <button type="button" className={s.cardActionBtn} onClick={() => openEdit(post.post_id)}>Edit</button>
                <button
                  type="button" className={s.cardActionBtnDanger}
                  disabled={deletingId === post.post_id}
                  onClick={() => handleDelete(post.post_id)}
                >
                  {deletingId === post.post_id ? 'Deleting…' : 'Delete'}
                </button>
              </div>
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

function BlogEditor({ post, onCancel, onSaved, authCtx }) {
  const { toast } = useApp();
  const [title, setTitle] = useState(post?.title || '');
  const [markdown, setMarkdown] = useState(post?.markdown_content || '');
  const [author, setAuthor] = useState(post?.author || '');
  const [coverImageUrl, setCoverImageUrl] = useState(post?.cover_image_url || '');
  const [status, setStatus] = useState(post?.status || 'draft');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);

  const isNew = !post?.post_id;

  const handleSave = async (publishNow) => {
    if (!title.trim() || !markdown.trim()) {
      setError('Title and content are both required.');
      return;
    }
    setSaving(true);
    setError(null);
    const finalStatus = publishNow ? 'published' : status;
    try {
      const payload = { title: title.trim(), markdown_content: markdown, status: finalStatus, author: author.trim(), cover_image_url: coverImageUrl.trim() };
      const saved = isNew
        ? await withTokenExpiry(blogPostsApi.create(payload), authCtx)
        : await withTokenExpiry(blogPostsApi.update(post.post_id, payload), authCtx);
      onSaved(saved);
    } catch (e) {
      if (e?.code !== 'TokenExpired') setError(e.message || 'Could not save this post.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className={s.page}>
      <SectionHeader
        title={isNew ? 'New Post' : 'Edit Post'}
        subtitle="Write in Markdown on the left — see exactly how it will look on the right."
        right={<button type="button" className={s.backBtn} onClick={onCancel}>← Back</button>}
      />

      <Card style={{ marginBottom: 16 }}>
        <div className={s.metaRow}>
          <div className={s.field}>
            <span className={s.fieldLabel}>Title*</span>
            <input className={s.input} value={title} onChange={e => setTitle(e.target.value)} placeholder="Your post title" />
          </div>
          <div className={s.field}>
            <span className={s.fieldLabel}>Author</span>
            <input className={s.input} value={author} onChange={e => setAuthor(e.target.value)} placeholder="Optional" />
          </div>
        </div>
        <div className={s.metaRow}>
          <div className={s.field} style={{ flex: 2 }}>
            <span className={s.fieldLabel}>Cover image URL</span>
            <input className={s.input} value={coverImageUrl} onChange={e => setCoverImageUrl(e.target.value)} placeholder="Optional — https://…" />
          </div>
          <div className={s.field}>
            <span className={s.fieldLabel}>Status</span>
            <select className={s.input} value={status} onChange={e => setStatus(e.target.value)}>
              <option value="draft">Draft</option>
              <option value="published">Published</option>
            </select>
          </div>
        </div>
      </Card>

      <div className={s.editorSplit}>
        <div className={s.editorPane}>
          <div className={s.paneLabel}>Markdown</div>
          <textarea
            className={s.markdownTextarea}
            value={markdown}
            onChange={e => setMarkdown(e.target.value)}
            placeholder={"# Heading\n\nWrite your post here using **Markdown** — lists, `code`, [links](https://example.com), and more."}
          />
        </div>
        <div className={s.editorPane}>
          <div className={s.paneLabel}>Preview</div>
          <div className={s.previewPane}>
            {markdown.trim() ? (
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{markdown}</ReactMarkdown>
            ) : (
              <span className={s.previewEmpty}>Your preview will appear here as you type.</span>
            )}
          </div>
        </div>
      </div>

      {error && <ErrorCard message={error} />}

      <div className={s.editorActions}>
        <button type="button" className={s.saveDraftBtn} disabled={saving} onClick={() => handleSave(false)}>
          {saving ? 'Saving…' : 'Save as Draft'}
        </button>
        <button type="button" className={s.publishBtn} disabled={saving} onClick={() => handleSave(true)}>
          {saving ? 'Publishing…' : 'Save & Publish'}
        </button>
      </div>
    </div>
  );
}

function BlogReader({ post, onBack, onEdit }) {
  return (
    <div className={s.page}>
      <div className={s.readerTopRow}>
        <button type="button" className={s.backBtn} onClick={onBack}>← All posts</button>
        <button type="button" className={s.editLinkBtn} onClick={onEdit}>Edit this post</button>
      </div>
      <Card>
        {post.cover_image_url && <img className={s.readerCover} src={post.cover_image_url} alt="" />}
        <div className={s.readerMeta}>
          <Badge variant={STATUS_VARIANT[post.status] || 'default'}>{post.status}</Badge>
          <span className={s.postDate}>{formatDate(post.updated_at)}{post.author ? ` · By ${post.author}` : ''}</span>
        </div>
        <h1 className={s.readerTitle}>{post.title}</h1>
        <div className={s.readerBody}>
          <ReactMarkdown remarkPlugins={[remarkGfm]}>{post.markdown_content}</ReactMarkdown>
        </div>
      </Card>
    </div>
  );
}
